      int start = i + 1;
      int depth = 1;
      int end = start;

      while (depth > 0 && end < chars.length) {
        if (chars[end] == '(') depth++;
        else if (chars[end] == ')') depth--;
        end++;
      }

      if (end >= chars.length || depth != 0) {
        throw FormatException('Unmatched parenthesis');
