      break;
    } else if (c == '[') {
      // Special case: handle [n], which adds n as an integer literal.
      int j = i + 1;
      bool isNumber = false;
      int number = 0;

      while (j < chars.length) {
        String nextChar = chars[j];
        if (nextChar == ']') {
