        j++;
      }

      if (j >= chars.length || chars[j] != ']') {
        throw FormatException('Invalid syntax at position $i');
      }

      // Add the parsed number to the result.
      result += number;

      i = j + 1;
    } else if (c == ',') {
      // Comma separates individual instructions within the same group.
      i++;
    } else {
