List<int> parseMusic(String musicString) {
  final List<int> result = [];

  int currentNote = -1;
  int lastStartIndex = -1;

  for (int i = 0; i < musicString.length; i++) {
    if (musicString[i] == ' ') {
      // End of a note, add it to the list
      if (lastStartIndex != -1 && currentNote != -1) {
        result.add(currentNote);
        currentNote = -1;
      }
      lastStartIndex = -1;
    } else if (musicString[i] >= 'A' && musicString[i] <= 'G') {
      // Start or continue a note
      if (currentNote == -1) {
        lastStartIndex = i;
        switch (musicString[i]) {
          case 'C': currentNote = 261; break;
          case 'D': currentNote = 293; break;
          case 'E': currentNote = 329; break;
          case 'F': currentNote = 349; break;
          case 'G': currentNote = 392; break;
          case 'A': currentNote = 440; break;
          case 'B': currentNote = 493; break;
          default: currentNote = -1;
        }
      } else {
        // Extend the note's duration by adding more characters
        final charCount = i - lastStartIndex + 1;
        if (charCount > 1) {
          final baseFrequency = getBaseFrequency(musicString[lastStartIndex]);
          const octaveMultiplier = pow(2.0, 1/12); 
          double frequency = baseFrequency * pow(octaveMultiplier, charCount - 1);
          result.add(frequency.round());
        }
      }
    }
  }

  return result;
}

