  if (l.isEmpty) return 0.0;

  final n = l.length;
  List<num> sortedList = List.from(l);
  sortedList.sort();

  int midIndex = n ~/ 2;

  if (n % 2 == 1) {
    // Odd number of elements, take the middle one
    return sortedList[midIndex];
  } else {
    // Even number of elements, average the two middle ones
    double sum = sortedList[midIndex - 1] + sortedList[midIndex];
    return sum / 2;
  }
}

