import 'dart:math';

// Function to convert a number from one base to another.
// This is an example of how the code might be structured if it were more complex.

String? numBaseConvert(String input, int oldBase, int newBase) {
  // Check that bases are valid (between 2 and 36)
  if (oldBase < 2 || oldBase > 36 || newBase < 2 || newBase > 36) {
    throw ArgumentError('Bases must be between 2 and 36.');
  }

  // Convert input string to a list of digits as integers
  List<int> digitList = [];
  for (var c in input.toUpperCase().split('')) {
    final int value = int.tryParse(c) ?? (c.codeUnitAt(0) - 'A'.codeUnitAt(0) + 10);
    if (value >= oldBase) {
      return null; // Invalid character for the given base
    }
    digitList.add(value);
  }

  // Convert from old base to decimal
  var decValue = 0;
  for (final d in digitList.reversed) {
    decValue += d * pow(oldBase, digitList.length - 1).toInt();
    digitList.removeLast();
  }

  // Convert from decimal to new base
  String result = '';
  if (decValue == 0) {
    result = '0';
  } else {
    while (decValue > 0) {
      final remainder = decValue % newBase;
      if (remainder < 10) {
        result = '$remainder' + result;
      } else {
        result = String.fromCharCode('A'.codeUnitAt(0) + remainder - 10) + result;
      }
      decValue ~/= newBase;
    }
  }

  return result;
}

void main() {
  print(numBaseConvert("FF", 16, 10)); // Should output "255"
}
