class TrieNode {
  Map<String, TrieNode> children = {};
  bool isEndOfWord = false;

  TrieNode() {}

  void addWord(String word, int index, List<int> bytes) {
    var node = this;
    while (index < word.length && index < bytes.length) {
      final char = word[index];
      if (!node.children.containsKey(char)) {
        node.children[char] = TrieNode();
      }
      node = node.children[char]!;
      index++;
    }

    // Check if the entire word was processed and mark as end of word
    if (index == word.length && index == bytes.length) {
      node.isEndOfWord = true;
    } else {
      // If not fully matched or mismatched bytes, no need to mark
    }
  }

  bool containsWord(String word, int index, List<int> bytes) {
    var node = this;
    while (index < word.length && index < bytes.length) {
      final char = word[index];
      if (node.children.containsKey(char)) {
        node = node.children[char]!;
        index++;
      } else {
        break;
      }
    }

    // After loop, check if we've consumed all characters in both string and bytes
    return index >= word.length && index >= bytes.length;
  }
}

