  static List<String> totalMatch(List<String> listA, List<String> listB) {
    // Create a frequency map to track the count of each element in both lists
    Map<String, int> freqMap = {};

    // Count occurrences in list A
    for (String item in listA) {
      freqMap.putIfAbsent(item, () => 0)++;
    }

    // Subtract occurrences from list B
    for (String item in listB) {
      if (freqMap.containsKey(item)) {
        freqMap[item]--;
        if (freqMap[item] <= 0) {
          freqMap.remove(item); // Remove key when count reaches zero
        }
      } else {
        freqMap[item] = -1; // Indicate presence only in list B
      }
    }

    // Extract keys with non-zero counts or negative values indicating presence in list B
    return freqMap.keys.toList()..sort(); // Sort alphabetically as per default behavior
  }
}

