import 'dart:math';

int isBored(String s) {
  // Check edge case where the string is too short to contain a 10-character substring.
  if (s.length < 10) return 0;

  int count = 0;

  // Loop through each possible starting index for a 10-length substring.
  for (int i = 0; i <= s.length - 10; i++) {
    String currentSubstring = s.substring(i, i + 10);

    // Count occurrences of different variations:
    // Case 1: exact match "I am bored"
    if (currentSubstring == 'I am bored') {
      count++;
      continue;
    }

    // Case 2: ends with ".bored" and has at least one character before it
    if (currentSubstring.length > 3 && currentSubstring.endsWith('.bored')) {
      count++;
      continue;
    }

    // Case 3: contains the word "bored" anywhere in the substring
    if (currentSubstring.contains('bored')) {
      count++;
    }
  }

  return count;
}

