int chooseNum(int x, int y) {
  if (x < 0 || y < 0) return -1;
  final n = min(x, y);
  final k = max(x, y);

  // Function to compute combination using Pascal's triangle and memoization
  Map<int, Map<int, int>> dp = {};
  List<List<int>> pascalTriangle = [];
  for (var i = 0; i <= k + 2; i++) {
    List<int> row = [1];
    for (var j = 1; j < i; j++) {
      row.add(0);
    }
    row.add(1);
    pascalTriangle.add(row);
  }

  void fillPascal() {
    for (var i = 1; i < pascalTriangle.length; i++) {
      for (var j = 1; j < i; j++) {
        pascalTriangle[i][j] = pascalTriangle[i - 1][j - 1] + pascalTriangle[i - 1][j];
      }
    }
  }

  fillPascal();

  int c(int a, int b) {
    if (b == 0 || a == b) return 1;
    if (a < b) return 0;

    var val = pascalTriangle[a][b];

    if (!dp.containsKey(a)) {
      dp[a] = {};
    }
    dp[a][b] = val;
    return val;
  }

  return c(n, k - n);
}
