import 'dart:async';

class C {
  static final _cache = <String, dynamic>{};
  static String key(int a, int b) => '$a,$b';

  static Future<int> factorial(int n) async {
    if (_cache.containsKey(key(n, 0))) return _cache[key(n, 0)] as int;
    if (n <= 1) return 1;
    final result = await Future.value(n * await factorial(n-1));
    _cache[key(n, 0)] = result;
    return result;
  }

  static Future<int> combinatorics(int n, int r) async {
    if (_cache.containsKey(key(n, r))) return _cache[key(n, r)] as int;
    if (r > n) return 0;
    if (r == 0) return 1;
    if (r == n) return 1;
    if (r > n / 2) return await combinatorics(n, n - r);

    final factN = await factorial(n);
    final factR = await factorial(r);
    final factNR = await factorial(n - r);
    final result = factN ~/ (factR * factNR);
    _cache[key(n, r)] = result;
    return result;
  }

  static Future<int> binomialCoefficient(int n, int k) => combinatorics(n, k);
}

Future<int> binomialCoefficients(int n, int k) => C.binomialCoefficient(n, k);
