List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Function to check if a path is valid
  bool isValid(int row, int col, int stepsTaken, Set<String> visitedCells) {
    return row >= 0 && row < rows &&
        col >= 0 && col < cols &&
        !visitedCells.contains('$row,$col') &&
        stepsTaken <= k;
  }

  // Directions: up, right, down, left
  List<Offset> directions = [
    Offset(-1, 0),
    Offset(0, 1),
    Offset(1, 0),
    Offset(0, -1)
  ];

  void dfs(int row, int col, int currentSum, int steps, Set<String> visited,
      List<int> result) {
    if (steps == k || row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
      result.add(currentSum);
      return;
    }

    for (var dir in directions) {
      var newRow = row + dir.dy.toInt();
      var newCol = col + dir.dx.toInt();

      if (isValid(newRow, newCol, steps + 1, visited)) {
        String cellKey = '$newRow,$newCol';
        if (!visited.contains(cellKey)) {
          visited.add(cellKey);
          dfs(
              newRow, newCol, currentSum + grid[newRow][newCol], steps + 1, visited,
              result);
          visited.remove(cellKey);
        }
      }
    }
  }

  Set<String> initialVisited = {'$0,0'};
  List<int> sumResult = [];
  dfs(0, 0, grid[0][0], 0, initialVisited, sumResult);

  return sumResult;
}

