import 'dart:io';

bool isNested(String string) {
  int openCount = 0;
  for (int i = 0; i < string.length; i++) {
    if (string[i] == '(') {
      openCount++;
    } else if (string[i] == ')') {
      if (openCount == 0) return false;
      openCount--;
    }
  }
  return openCount == 0 && string.isNotEmpty;
}

