List<String> factorize(String numStr) {
  int number = int.parse(numStr).abs();
  if (number <= 1) return ['1'];

  List<String> factors = [];
  for (var d = 2; d * d <= number; d += 1) {
    while (number % d == 0) {
      factors.add(d.toString());
      number ~/= d;
    }
  }
  if (number > 1) factors.add(number.toString());

  return factors;
}
