List<int> eat(int number, int need, int remaining) {
  if (number == 0 || remaining < 1) return [0];

  final eaten = min(need, remaining);
  final leftOver = remaining - eaten;

  // The total amount of food the bird can consume is
  // either the full need or what's available.
  final totalConsumed = eaten + number * leftOver;

  // If there's still more to eat than needed,
  // subtract the excess from the leftovers.
  if (totalConsumed > need) {
    final extraLeftover = leftOver - (totalConsumed - need);

    // Ensure that we don't have negative leftover since it doesn't make sense.
    final actualLeftover = max(extraLeftover, 0); 
    return [eaten + (totalConsumed - need), actualLeftover];
  } else {
    return [totalConsumed, leftOver];
  }
}

